b4bdd73063e2633ac86a035fe0f1d05455f34300a706595e1eda0b3e69","plugin":"lean4","revision":"builtin","sent":true},{"name":"lean_file","digest":"2ab5d5e0be1cd409ca1f1750188c22d30d348ff8e05e3eef05213b6f1949e514","shown":"2ecc3fc0394a69cfe124bfef6d16e8064bec73ce0c78fa3b45537bc148badf55","plugin":"lean4","revision":"builtin","sent":true},{"name":"lean_project","digest":"285cc8b24896bd340e3892e6afc92929fe7c20284f2aac88b4555ddde30d1dc9","shown":"486ce8aaad71c850bb7800c4e4fa4588509bd995655b178aacdc29e15b4750d5","plugin":"lean4","revision":"builtin","sent":true},{"name":"lean_inspect","digest":"01bbb95a4d01bc04ea9a5fad8f02e746b587586a152d63d5fd043ea6f201845a","shown":"eb9feafa7eced29ff2ad606409ede470f1df239f215b98145ace7291af01af3b","plugin":"lean4","revision":"builtin","sent":true},{"name":"lean_loogle","digest":"972410e9735bcf8e98dc75d6caf1ebacb52430e8245d6ed0417d4332220c5e1b","shown":"fe587488828382b4e41c85d111a844920cf673a1ecec4ad93572f48cdc834152","plugin":"lean4","revision":"builtin","sent":true},{"name":"script","digest":"266a6876884ce9ef66eeb1db2a9cf0455c9f977c73d0c9fc67c084ef4fdb4c80","shown":"bf8d30b832b29d130339ac72c697680d3e79ce6c721ec88a0e2d326bd82ed686","plugin":"codemode","revision":"builtin","sent":true},{"name":"executions","digest":"ef471b1aad1e94ef926cdef546c5045c596750e5a3da09c5e7d3c0a67ed196c4","shown":"e94f704f9adc8b84b91c44ee77b284cac51ec7ca28813cc2dd49bf83bf704a9a","plugin":"memory-workflow","revision":"builtin","sent":true},{"name":"resources","digest":"43916e196455198bc2c0143884ccefbded226a6d3fd09b53aa4cf2016cd2f5a6","shown":"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5","plugin":"memory-workflow","revision":"builtin","sent":true},{"name":"context","digest":"08a862c8adc6f7b2d7537ce177a2eec36c90234c31dd7f579f0e781f905e86a2","shown":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","plugin":"codemode","revision":"builtin","sent":true},{"name":"self","digest":"1c6b9cb253f5db53e49383c8d70c38e86cae1b6f88d71fce5c8003f618