INSERT INTO event VALUES(244,5,4,'context.blob',1,1767225844000,'{"payload":{"digest":"7732e8362f85184ccba7d8588a94911bec7de3ffb84d954b290b27ceb93feccf","value":"{\"delegation\":{\"agents\":[],\"models\":[\"openai/gpt-6.1-sol\",\"openai/gpt-5.6-terra\",\"openai/gpt-6-luna\",\"deepseek/deepseek-flash\",\"deepseek/deepseek-v4-pro\"],\"worktree\":false},\"sections\":{\"core plugin\":\"For math in responses, use $...$ or \\\\(...\\\\) for inline and $$...$$ or \\\\[...\\\\] for display math. Wrap LaTeX environments like align or gather inside $$...$$ (e.g., $$\\\\begin{align}...\\\\end{align}$$) so they render correctly.\",\"tool-call\":\"Independent tool calls may be issued together in one response. Sequence only calls that depend on an earlier result.\"},\"tools\":[\"script\",\"agent\",\"document_context\",\"document_extract\",\"document_compile\",\"document_diff\",\"document_review\",\"document_propose\",\"self\"]}"}}');
