INSERT INTO event VALUES(421,8,21,'context.blob',1,1767226021000,'{"payload":{"digest":"6eb8905af7aed07a90df25905c1918b8891286effa2de5b715472eee0b411937","value":"{\"agent\":\"e4400188af49525d692ef3a2637e1ed353135253d77f6aa06155cfe4758b17b4\",\"controls\":{\"maxOutputTokens\":128000,\"promptCacheKey\":\"a00000000008\",\"reasoning\":null,\"serviceTier\":null,\"store\":false,\"temperature\":0,\"toolChoice\":\"auto\"},\"mode\":\"foreground\",\"system\":\"d7f09a1b2ca38c5efc1e2044264a3e5bbd0d1a52968efdb84f5a915b47f741f7\",\"tools\":[\"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1\",\"d9362d87c2e2a7abe053247649f3a41e0c9a2b06dc02a63b32b890074f9f4996\",\"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f\",\"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14\",\"c7cb7ca529600dfe0965e682c6109f84d037ccd0a2f90fa1d5610c48d136b838\",\"2a28b57fff4ee9496c278238dbf33992fc0099f08ed567fd224b59eac182ffb9\",\"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5\",\"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675\"]}"}}');
INSERT INTO event VALUES(422,8,22,'model.message',22,1767226022000,'{"payload":{"kind":"attempt","invocation":{"invocationId":"00000000-0000-4000-8000-000000000044","attempt":1},"request":"6eb8905af7aed07a90df25905c1918b8891286effa2de5b715472eee0b411937","origin":{"protocol":"openai-responses","requestedModel":"gpt-5.6-sol","deployment":{"endpoint":"https://validation.invalid/v1","credentialScope":"validation"},"codecVersion":1}}}');
INSERT INTO event VALUES(423,8,23,'model.message',22,1767226023000,'{"payload":{"kind":"response","responseId":"00000000-0000-4000-8000-000000000045","invocation":{"invocationId":"00000000-0000-4000-8000-000000000044","attempt":1},"turn":{"providerResponseId":"validation-response-1","requestedOrigin":{"protocol":"openai-responses","requestedModel":"gpt-5.6-sol","deployment":{"endpoint":"https://validation.invalid/v1","credentialScope":"validation"},"codecVersion":1},"returnedModel":"gpt-5.6-sol","content":[{"kind":"local-call","providerCallId":"validation-plan-1","name":"plan","argumentsText":"{\"objective\":\"Answer the golden chat, then stop.\"}"}],"finishReason":"tool-calls","usage":{"inputTokens":1,"outputTokens":1,"totalTokens":2,"cachedInputTokens":null,"cacheWriteTokens":null,"reasoningTokens":null,"toolUsePromptTokens":null}},"calls":[{"callId":"validation-plan-1","toolName":"plan","lane":"barrier","replay":"unsafe","duplicateOf":null,"logId":"00000000-0000-4000-8000-000000000046"}],"usage":{"inputTokens":1,"outputTokens":1,"cost":0.000024,"usageRoute":"api-key","responseTimeMs":0,"provider":"openai-responses"}}}');
