INSERT INTO event VALUES(425,8,25,'tool.intent',2,1767226025000,'{"payload":{"origin":{"kind":"response","responseId":"00000000-0000-4000-8000-000000000045"},"callId":"validation-plan-1","attempt":1,"logId":"00000000-0000-4000-8000-000000000046","toolName":"plan","input":{"objective":"Answer the golden chat, then stop."}}}');
