INSERT INTO event VALUES(428,9,1,'run.start',7,1767226028000,'{"identity":{"kind":"script","title":"Goal"},"takesFollowUps":true,"worktree":{"workingDirectory":"/golden/project"},"parent":{"id":"a00000000008","uid":"00000000-0000-4000-8000-000000000008","call":{"callId":"validation-plan-1","card":"00000000-0000-4000-8000-000000000046","awaited":false}},"provenance":null,"grants":{"own":{},"goal":["bash"]},"maxCostUsd":null}');
