INSERT INTO event VALUES(552,11,22,'context.blob',1,1767226152000,'{"payload":{"digest":"206ce123f2ac56803e71fd7a1202c8235bdd7834e978dfa9fd7ba016e65de772","value":"{\"agent\":\"e4400188af49525d692ef3a2637e1ed353135253d77f6aa06155cfe4758b17b4\",\"controls\":{\"maxOutputTokens\":128000,\"promptCacheKey\":\"af2b42e263afafa73834e36b\",\"reasoning\":null,\"serviceTier\":null,\"store\":false,\"temperature\":0,\"toolChoice\":\"auto\"},\"mode\":\"foreground\",\"system\":\"ffed2f18b771b7654c0f49087cf2c13ac3645de17de832c7e6c9db2d3e4f8e53\",\"tools\":[\"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1\",\"d9362d87c2e2a7abe053247649f3a41e0c9a2b06dc02a63b32b890074f9f4996\",\"97e33fc965755d32f598352474eb78e7bcd3bd9090776d9562c09c9bd51fd56f\",\"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14\",\"c7cb7ca529600dfe0965e682c6109f84d037ccd0a2f90fa1d5610c48d136b838\",\"2a28b57fff4ee9496c278238dbf33992fc0099f08ed567fd224b59eac182ffb9\",\"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5\",\"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675\",\"9f8f4f84ee88464c94f4d30700db297bc64ef39bba74b97a93e498f3af9444c6\"]}"}}');
