INSERT INTO event VALUES(720,13,62,'tool.result',6,1767226320000,'{"stageId":"00000000-0000-4000-8000-00000000006e","payload":{"responseId":"00000000-0000-4000-8000-00000000006d","callId":"validation-script-1/2","attempt":1,"logId":"00000000-0000-4000-8000-000000000071","disposition":"executed","duplicateOf":null,"result":{"status":"executed","output":"     1\t\\section{Notes}\n     2\tThe golden store reads this file.","summary":"Read notes.tex","reads":["notes.tex"]},"attachments":[]}}');
