INSERT INTO event VALUES(724,13,66,'script.call',3,1767226324000,'{"payload":{"scriptCallId":"validation-script-1","seq":4,"callId":"validation-script-1/4","toolName":"agent","input":{"label":"Defined agent","system":"GOLDEN-CHILD: answer the task.","tools":["read_file","executions"],"prompt":"Answer from the notes."},"replay":"safe","logId":"00000000-0000-4000-8000-000000000073","section":"Gather"}}');
