INSERT INTO event VALUES(854,18,8,'context.blob',1,1767226454000,'{"payload":{"digest":"2cf24576e72aa687df224a7a5037639917077bc04a67b4fef3ba72649d863a14","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are the ones to read at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"create\\\".\"},\"insert_line\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\".\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"insert\\\": Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"new_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\" or \\\"insert\\\".\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"rename\\\": Path under /memories (e.g. /memories/notes.md).\"},\"old_str\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"str_replace\\\".\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\": Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted. With command \\\"create\\\", \\\"str_replace\\\", \\\"insert\\\", \\\"delete\\\", \\\"pin\\\", or \\\"unpin\\\": Path under /memories (e.g. /memories/notes.md).\"},\"view_range\":{\"anyOf\":[{\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line, inclusive and 1-indexed; the end of the file when omitted.\"},\"start\":{\"description\":\"First line, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"items\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}]}]},\"maxItems\":2,\"minItems\":1,\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"With command \\\"view\\\".\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(855,18,9,'context.blob',1,1767226455000,'{"payload":{"digest":"c607cf9bd7fe97fea9e23a46d7b3d3bee54964795a6fa329db90b93962916aa5","value":"{\"description\":\"Read the resources you have now. Takes no arguments and changes nothing.\\n\\nIt answers:\\n- `now`: the current time in this machine''s zone: ISO 8601 with its UTC offset, then the zone''s name in brackets. Every time in the answer is written the same way.\\n- `models`: the models a run can use now, each with `billing` (the subscription plan its next request is paid by, or `api-key:<provider>`) and its listed prices in US dollars per million tokens (input, cached input, output; `aboveInputTokens` when a longer prompt is billed at other rates). A request paid by a plan costs nothing per token; the listed prices are what the provider''s API key is billed.\\n- `plans`: each subscription plan, whether it carries requests now (`on`), and what is known of its quota: each window''s share remaining and when it resets, with `asOf`, when that was learned and from which `source`. A plan''s quota endpoint is asked at most every 30 seconds; a plan whose replies state its quota is known only as of its last reply, which may be long ago. `failed` names why a quota read gave nothing; `unknown` says why nothing is known.\\n- `spend`: what this run has spent in US dollars (`runUsd`), and with every run it started (`treeUsd`), and `caps`: each spend cap this run or a run it belongs to was started with; that run and the runs it started are stopped once their spend reaches `maxCostUsd`.\\n\\nA field that could not be read is replaced by one that says why (`modelsUnknown`, `plansUnknown`).\",\"name\":\"resources\",\"parameters\":{\"properties\":{},\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(856,18,10,'context.blob',1,1767226456000,'{"payload":{"digest":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","value":"{\"description\":\"Read or edit your own context: the messages each of your requests sends.\\n\\n- view: each message with its index, role, kind, estimated tokens and a preview; the window size and the tokens in use; and the replacements this response already asked for.\\n- replace: messages [from, to) are replaced, before your next request, by one message holding `with`. Indices are the view''s, as this response was sent; ranges asked for in one response must not overlap. The range ends at or before the response that makes the call, and keeps each tool call with its results.\\n\\nThe replaced messages stay in the stored history: the person still sees them, and the executions tool, where offered, reads them back (/executions/current/conversation). A replacement ends prompt-cache reuse from its first message on, and any provider-side continuation, so the next request pays full input price for everything after that point. Keep what the user asked of you, in substance.\",\"name\":\"context\",\"parameters\":{\"properties\":{\"action\":{\"anyOf\":[{\"enum\":[\"view\",\"replace\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"\\\"view\\\": Read the view (the default).\"},\"from\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index of the first message replaced.\"},\"to\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": Index after the last message replaced.\"},\"with\":{\"anyOf\":[{\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"With action \\\"replace\\\": The text that stands in for those messages.\"}},\"type\":\"object\"}}"}}');
