wn":"b3b2a3d44f4a95de0455196ad7ead418771471fafd4c8ed975d4774b7c4fe2a1","plugin":"goal","revision":"builtin","sent":true},{"name":"context","digest":"08a862c8adc6f7b2d7537ce177a2eec36c90234c31dd7f579f0e781f905e86a2","shown":"8a2319aaf4d5a9441e58b42c2cd4eb259778d07d1187cc2cd49bf8e068886675","plugin":"codemode","revision":"builtin","sent":true},{"name":"self","digest":"1c6b9cb253f5db53e49383c8d70c38e86cae1b6f88d71fce5c8003f618915723","shown":"68658b6c4997ca7c56924c7911f8fc962eb09157a11aa139f5bba01ca0caea61","plugin":"codemode","revision":"builtin","sent":false}],"skills":[],"system":"056a03b7fb6f3f68c8f52244ca86823ba41b8d099e93e9b42feec067d25005d1","context":"74ef4df2bfdec2a3c6070cde44ae95b9c4cb30241be317edf6bc2aa62a9d93ff","hooks":[],"modules":{"builtIn:goal":"3bc0578f5d563ba463ad8cb7f81519927bd7e7c185d9005529045e9266322a83","builtIn:rounds":"7a5d27e235e3f9b1f30135e6eb9518f2872302bb2ef007f302834e08acae995f","builtIn:prove":"dd44db81912b241a84b811cbecfc7789e089eb1375f36a1f2a26d3cf2c6af9a1","builtIn:lean-simplify":"a6ca2ee1de6b99808ba532e1e6d14e44eab626843d1691ef6a703112bf4d67dd","builtIn:blueprint":"d8392a717df1e518da4fa4474c272fb2481e2548c9af35344c68154c1b4fdecb","builtIn:lean-search":"7a434e44b213bd729a1d2a1ef8cd05c300b917e6bec7d3639b67732d9cd38d06","builtIn:task":"9c61c66bf4e6019a8ae6f7bb7a3d166aed77e8eca46a2fccae017032c5e63d2f","builtIn:review":"2316b98449a5219f93aaab6f6556de1ad5c0dc24db9706fd7d96be705c06b785","builtIn:search":"4adb23a0be55216646a28756ee307398ea1d52f7772ec3d67a752b020634e21a","builtIn:derive":"f8f3f709a284cd3ee373da9bf23204d2b6899f501e10c0b713d692d98693274a","builtIn:code":"ea5f1026719a9bb55816295fbce703d20187c7d85b8b584cac5d4cd306b6760a","builtIn:review-code":"598d801258debd6eb19d966a902dd2452ae0e29bdc81f23d06b5874465e05de3","builtIn:simplify":"6951c488bfaa6f4889dafcdfe3e865c374d13be121541d955bf10ce7a487e90d","builtIn:test":"c7c1719098ac6fe47ea208135b0bec59696836054fbc4a9abd4ca5ab97b2e5a1","builtIn:experiment":"ae1198abe4a20e9aaa5b2a49a1a1ac2edb62